export function DisabledState({
  label = "{{label}}",
  accent = "{{accent}}",
  force = {{force}},
  radius = {{radius}},
}) {
  return (
    <div style={{ width: 260, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, textAlign: "center" }}>
      <button type="button" disabled={force}
        style={{ font: "700 15px system-ui, sans-serif", padding: "11px 22px", borderRadius: radius, border: `2px solid ${accent}`, background: accent, color: "#FAF7F2", cursor: force ? "not-allowed" : "pointer", opacity: force ? 0.4 : 1, filter: force ? "grayscale(.3)" : "none" }}>
        {label}
      </button>
      <p style={{ margin: "12px 0 0", fontSize: 11, color: "#241430888", textAlign: "left" }}>Real <code>disabled</code> attribute — the browser blocks clicks and focus on its own; <code>:disabled</code> supplies the look.</p>
    </div>
  );
}
